function ActivityBossChallengeRewardDialog:OnGetItemByIndex(listView, listIndex)
    if listIndex < 0 then return end
    local cell = listView:NewListViewItem("Cell")
    ---@type LadderCompetionTaskRewardCellNode
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, TaskCellNodeLuaPath)
    if nodeEnv then
        local luaIndex = listIndex + 1
        local cellData = {taskVo = checkTable(self._playerPointRewards[luaIndex])}
        cellData.taskVo.desc = localize("点数达到_num_", {_num_ = cellData.taskVo.needNum})
        cellData.taskData = {progress = self._playerPointNum, status = cellData.taskVo.status}
        cellData.taskVo.taskContenNum = cellData.taskVo.needNum
        -- init cell
        nodeEnv:SetLuaIndex(luaIndex)
        nodeEnv:SetCellData(cellData)
        nodeEnv:SetClickCB(Bind(self, self.ListCellOnClickHandler))
        -- init anim
        if self._itemShowNum == nil then
            local cellSizeH   = cell.CachedRectTransform.rect.height + cell.Padding
            self._itemShowNum = math.ceil(self.RewardLoopView.ViewPortHeight / cellSizeH)
        end
        if not self._cellAnimMap[luaIndex] and listIndex <= self._itemShowNum then
            self._cellAnimMap[luaIndex] = true
            nodeEnv:PlayDelayAnimByShow(listIndex)
        else
            nodeEnv:PlayAnimByIdle()
        end
    end
    return cell
end

