---排序
function ActivityBossChallengeRewardDialog:SortRewardsList()
    table.sort(self._playerPointRewards, function(a, b)
        if a.status == b.status then
            return a.id < b.id
        else
            if checkNumber(a.status) == 1 then
                return true
            elseif checkNumber(b.status) == 1 then
                return false
            else
                return checkNumber(a.status) < checkNumber(b.status)
            end
        end
    end)
end
--endregion private

